#include <set>
#include <string>

struct User {
    int id;
    std::string name;
};

// Custom comparator that compares only the ID
struct CompareUser {
    bool operator()(const User& a, const User& b) const {
        return a.id < b.id;
    }
};

int main() {
    std::set<User, CompareUser> user_set;
    User u1 = {101, "Alice"};
    User u2 = {101, "Bob"}; // Same ID, different name

    user_set.insert(u1);
    user_set.insert(u2); // Insertion fails because: 
                         // !(u1 < u2) && !(u2 < u1) is true.
                         // The set treats u1 and u2 as equal.

    // user_set.size() will be 1.
}
